            new RailwayWisdomRule("SIG-002", "Signals", "Signal", "Diagnostic", "Derived", "Zero on unselected aspect is expected", "Voltage/current near zero on an aspect that was not commanded is normal de-energization; it becomes suspicious only when that aspect was commanded and coverage is healthy.", "Prove aspect command and time window, then compare paired voltage/current, proving relay, supply bus, and neighboring signals.", "Do not diagnose open circuit from zero on a dark or unselected aspect.", "IRSEM-2021", "7.1.12; 21.1.9", "134-135; 440-442", "signal zero unselected dark aspect commanded open circuit", 95, "IRSEM-CH07-X"),
            new RailwayWisdomRule("SIG-003", "Signals", "Signal", "Safety", "Normative", "Power failure must not leave approaching stop signal blank", "The signalling power system must be arranged so fixed stop signals for an approaching train do not become blank when main supply fails.", "Correlate aspect loss with signal supply, IPS output, changeover, battery, and other signals on the same feed.", "Do not assume blank signal is lamp-only fault when common supply is abnormal.", "IRSEM-2021", "16.1.1(c)", "323", "signal blank main power failure IPS changeover common supply", 94, ""),
            new RailwayWisdomRule("SIG-004", "Signals", "Signal", "Diagnostic", "Derived", "Voltage-current patterns localize fault domain", "Command with voltage but no current supports downstream open-load investigation; voltage and current without proving supports lamp/LED, optical, or proving-path issues; several aspects lost supports common supply/cable investigation.", "Verify circuit design, paired channels, calibration, feed point, proving relay, cable insulation, and neighboring loads.", "Do not assert a component failure from pattern alone; intrusive tests require approved protection and competent staff.", "IRSEM-2021", "11.1.2; 16.3.1; 19.10.1; 21.1.9", "220; 325; 406-407; 440-442", "signal voltage current open load proving common feed", 86, ""),
            new RailwayWisdomRule("SIG-005", "Signals", "Signal", "Principle", "Normative", "Aspect sequence remains restrictive", "When a signal displays Stop, the signal in rear must not display less restrictive than Caution; caution/attention repetition covers inadequate braking distance or divergence.", "Compare complete rear-to-front sequence, route, divergence, and approved control table.", "Do not judge one signal's aspect without next signal and route context.", "IRSEM-2021", "7.1.15", "137-138", "aspect sequence stop caution attention rear signal divergence", 83, "IRSEM-CH07-X"),
            new RailwayWisdomRule("SIG-006", "Signals", "Signal", "Maintenance", "Normative", "Signal visibility is a maintained safety property", "Signal sighting, interference by other lights, vegetation, structures, boards, and day/night visibility require periodic foot-plate inspection and action.", "Link sighting reports to current certificate and day/night inspection evidence.", "Do not explain an electrically normal signal event solely by visibility without field observation.", "IRSEM-2021", "3.1.3; 7.1.5; 7.1.11", "14; 132-135", "signal visibility sighting vegetation lights day night", 60, "IRSEM-CH03-X;IRSEM-CH07-X"),
            new RailwayWisdomRule("SIG-007", "Signals", "Signal", "Testing", "Normative", "De-energize each controlling input during tests", "Signal-control testing includes de-energizing each controlling track and point relay and proving signal returns to danger.", "Use approved control table, test each control independently, record result/restoration, and maintain train protection.", "Do not simulate or bypass controls on working installation outside sanctioned procedure.", "IRSEM-2021", "19.8.9", "402-404", "signal control test deenergize relay danger control table", 82, ""),
            new RailwayWisdomRule("PNT-001", "Points", "Point Machine", "Principle", "Normative", "Point operation requires free interlocking and clear track", "A point may operate only when interlocking is free and its track circuit clear; emergency operation is separate, controlled, and counted.", "Check TPR, route/approach locking, command source, emergency counter, crank handle, and point-control outputs.", "Do not call missing operation a machine failure when interlocking correctly withheld command.", "IRSEM-2021", "7.4.4; 21.1.12", "150; 442-446", "point command interlocking free track clear TPR emergency", 96, "IRSEM-CH07-X"),
            new RailwayWisdomRule("PNT-002", "Points", "Point Machine", "Diagnostic", "Derived", "Both detections down is normal during commanded transition", "NWKR and RWKR may both be down while a point moves; suspicion requires this state outlast configured operation interval or persist after command should complete.", "Prove command start, point type, normal time, motor current, cutoff, end detection, and coverage.", "Do not label a transition sample or uncommanded unproved state as completed-operation failure.", "IRSEM-2021", "Annexure 11-A1 items 4-5; 19.3.2", "225; 391-393", "NWKR RWKR both down transition duration point failure", 98, ""),
            new RailwayWisdomRule("PNT-003", "Points", "Point Machine", "Testing", "Normative", "Five-millimeter obstruction prevents lock and detection", "With a 5 mm obstruction at the specified position, the point must not lock, detection must not indicate closure, and friction clutch should slip.", "Perform only under approved protection; verify both ends where applicable, indication, lock, clutch, and relevant signals.", "Do not infer a passed obstruction test from normal telemetry alone.", "IRSEM-2021", "7.4.2; 19.3.2", "150; 392", "5 mm obstruction point lock detection friction clutch", 91, "IRSEM-CH07-X"),
