            new RailwayWisdomRule("PNT-009", "Points", "Point Machine", "Protection", "Normative", "Overload cutoff requires fresh operation", "On obstruction motor feed cuts off; restoration follows a fresh operation, with cutoff constrained relative to normal time.", "Check overload timing, fresh command, cutoff/reconnect, clutch, and normal time.", "Do not repeatedly energize an obstructed point as diagnostic experiment.", "IRSEM-2021", "19.3.2", "391-393", "point overload cutoff fresh operation obstruction motor feed", 86, ""),
