            new RailwayWisdomRule("TRK-001", "Track Circuits", "Track Circuit", "Principle", "Normative", "Closed track circuit proves clearance", "A closed track circuit is energized to prove rail clearance; de-energized track relay means occupied or failed/unproved, not automatically equipment failure.", "Check occupancy, TPR, feed/relay values, adjacent sequence, bobbing, and duration.", "Do not label every TPR down interval as fault.", "IRSEM-2021", "17.1.1", "331", "closed track circuit clearance TPR down occupied failed unproved", 98, ""),
