        private sealed class ScoredRule { public RailwayWisdomRule Rule; public int Score; }

        public static RailwayWisdomRule GetRule(string id)
        {
            if (String.IsNullOrEmpty(id)) return null;
            for (int i=0; i<Rules.Length; i++)
                if (String.Equals(Rules[i].Id, id, StringComparison.OrdinalIgnoreCase)) return Rules[i];
            return null;
        }

        public static List<RailwayWisdomRule> FindRules(string assetFamily, string query, int maxRules)
        {
            if (maxRules < 1) maxRules = 1; if (maxRules > 40) maxRules = 40;
            string asset=Normalize(assetFamily), q=Normalize(query); string[] tokens=Tokenize(q);
            List<ScoredRule> scored=new List<ScoredRule>();
            for (int i=0; i<Rules.Length; i++)
            { int score=Score(Rules[i], asset, q, tokens); if (score>0) scored.Add(new ScoredRule { Rule=Rules[i], Score=score }); }
            scored.Sort(delegate(ScoredRule a, ScoredRule b) {
                int x=b.Score.CompareTo(a.Score); if (x!=0) return x;
                x=b.Rule.Priority.CompareTo(a.Rule.Priority); if (x!=0) return x;
                return StringComparer.Ordinal.Compare(a.Rule.Id,b.Rule.Id); });
            List<RailwayWisdomRule> result=new List<RailwayWisdomRule>();
            for (int i=0; i<scored.Count && result.Count<maxRules; i++) result.Add(scored[i].Rule);
            return result;
        }

        public static string BuildPrompt(string assetFamily, string query, int maxRules)
        {
            List<RailwayWisdomRule> selected=FindRules(assetFamily,query,maxRules); StringBuilder sb=new StringBuilder();
            sb.AppendLine("RAILWAY SIGNALLING WISDOM " + Version); sb.AppendLine(SafetyContract);
            sb.AppendLine("Evidence: Normative=requirement; Example=manual example; Derived=hypothesis needing corroboration.");
            for (int i=0; i<selected.Count; i++) { RailwayWisdomRule r=selected[i];
                sb.Append("[").Append(r.Id).Append(" | ").Append(r.Evidence).Append("] ").AppendLine(r.Title);
                sb.Append("Wisdom: ").AppendLine(r.Statement); sb.Append("Check: ").AppendLine(r.RequiredChecks);
                sb.Append("Guard: ").AppendLine(r.DoNotInfer); sb.Append("Source: ").Append(r.SourceId).Append(" cl. ").Append(r.Clause).Append(", printed p. ").AppendLine(r.PrintedPage); }
            return sb.ToString();
        }

        private static int Score(RailwayWisdomRule r, string asset, string q, string[] tokens)
        {
            string ra=Normalize(r.AssetFamily); string h=Normalize(r.Domain+" "+r.AssetFamily+" "+r.Kind+" "+r.Title+" "+r.Statement+" "+r.RequiredChecks+" "+r.Keywords); int score=0;
            if (r.Id.StartsWith("SAF-",StringComparison.Ordinal)) score+=2;
            if (!String.IsNullOrEmpty(asset)) { if (ra=="ALL") score+=1; else if (ra==asset) score+=12; else if (ra.IndexOf(asset,StringComparison.Ordinal)>=0 || asset.IndexOf(ra,StringComparison.Ordinal)>=0) score+=7; }
            if (!String.IsNullOrEmpty(q) && h.IndexOf(q,StringComparison.Ordinal)>=0) score+=8;
            for (int i=0; i<tokens.Length; i++) if (tokens[i].Length>2 && h.IndexOf(tokens[i],StringComparison.Ordinal)>=0) score+=2;
            if (String.IsNullOrEmpty(asset) && String.IsNullOrEmpty(q)) score=r.Priority; return score;
        }

        private static string Normalize(string value)
        {
            if (String.IsNullOrEmpty(value)) return String.Empty; StringBuilder sb=new StringBuilder(value.Length); bool space=false;
            for (int i=0; i<value.Length; i++) { char c=Char.ToUpperInvariant(value[i]);
                if (Char.IsLetterOrDigit(c)) { if (space && sb.Length>0) sb.Append(' '); sb.Append(c); space=false; } else space=true; }
            return sb.ToString();
        }

        private static string[] Tokenize(string value)
        { if (String.IsNullOrEmpty(value)) return new string[0]; return value.Split(new char[] { ' ' }, StringSplitOptions.RemoveEmptyEntries); }
    }
}
